L32: pub(crate) fn select_handlers_for_matcher_inputs(
L33:     handlers: &[ConfiguredHandler],
L34:     event_name: HookEventName,
L35:     matcher_inputs: &[&str],
L36: ) -> Vec<ConfiguredHandler> {
L37:     // Check each configured handler once, even when several compatibility names
L38:     // match the same regex. A hook like `apply_patch|Write|Edit` should run a
L39:     // single time for one tool call, not once per matching alias.
L40:     handlers
L41:         .iter()
L42:         .filter(|handler| handler.event_name == event_name)
L43:         .filter(|handler| match event_name {
L44:             HookEventName::PreToolUse
L45:             | HookEventName::PermissionRequest
L46:             | HookEventName::PostToolUse
L47:             | HookEventName::SessionStart
L48:             | HookEventName::SessionEnd
L49:             | HookEventName::SubagentStart
L50:             | HookEventName::SubagentStop
L51:             | HookEventName::PreCompact
L52:             | HookEventName::PostCompact => {
L53:                 if matcher_inputs.is_empty() {
L54:                     matches_matcher(handler.matcher.as_deref(), /*input*/ None)
L55:                 } else {
L56:                     matcher_inputs
L57:                         .iter()
L58:                         .any(|input| matches_matcher(handler.matcher.as_deref(), Some(input)))
L59:                 }
L60:             }
L61:             HookEventName::UserPromptSubmit | HookEventName::Stop => true,
L62:         })
L63:         .cloned()
L64:         .collect()
L65: }
