L84: pub(crate) async fn execute_handlers<T>(
L85:     shell: &CommandShell,
L86:     handlers: Vec<ConfiguredHandler>,
L87:     input_json: String,
L88:     cwd: &Path,
L89:     turn_id: Option<String>,
