L91: ) -> Vec<ParsedHandler<T>> {
L92:     let mut pending = FuturesUnordered::new();
L93:     for (configured_order, handler) in handlers.into_iter().enumerate() {
L94:         let input_json = input_json.clone();
L95:         let turn_id = turn_id.clone();
L96:         pending.push(async move {
L97:             let result = run_command(shell, &handler, configured_order, &input_json, cwd).await;
L98:             (configured_order, parse(&handler, result, turn_id))
L99:         });
L100:     }
L101:     let mut completed = Vec::new();
L102:     let mut completion_order = 0;
L103:     while let Some((configured_order, mut parsed)) = pending.next().await {
L104:         parsed.completion_order = completion_order;
L105:         completion_order += 1;
L106:         completed.push((configured_order, parsed));
L107:     }
L108:     completed.sort_by_key(|(configured_order, _)| *configured_order);
L109:     completed.into_iter().map(|(_, parsed)| parsed).collect()
L110: }
