L166:         cwd: turn_context.cwd.clone(),
L167:         transcript_path: sess.hook_transcript_path().await,
L168:         model: turn_context.model_info.slug.clone(),
L169:         permission_mode: hook_permission_mode(turn_context),
L170:         tool_name: tool_name.name().to_string(),
L171:         matcher_aliases: tool_name.matcher_aliases().to_vec(),
L172:         tool_use_id,
L173:         tool_input: tool_input.clone(),
L174:     };
L175:     let hooks = sess.hooks();
L176:     let preview_runs = hooks.preview_pre_tool_use(&request);
L177:     emit_hook_started_events(sess, turn_context, preview_runs).await;
L178:     let PreToolUseOutcome {
L179:         hook_events,
L180:         should_block,
L181:         block_reason,
L182:         additional_contexts,
L183:         updated_input,
L184:     } = hooks.run_pre_tool_use(request).await;
L185:     emit_hook_completed_events(sess, turn_context, hook_events).await;
L186:     record_additional_contexts(sess, turn_context, additional_contexts).await;
L187: 
L188:     if !should_block {
L189:         return PreToolUseHookResult::Continue { updated_input };
L190:     }
L191:     let Some(reason) = block_reason else {
L192:         return PreToolUseHookResult::Continue {
L193:             updated_input: None,
L194:         };
L195:     };
L196:     if (tool_name.name() == "Bash" || tool_name.name() == "apply_patch")
L197:         && let Some(command) = tool_input.get("command").and_then(Value::as_str)
L198:     {
