L281: pub(crate) async fn run_turn_stop_hooks(
L282:     sess: &Arc<Session>,
L283:     turn_context: &Arc<TurnContext>,
L284:     stop_hook_active: bool,
L285:     last_assistant_message: Option<String>,
L286: ) -> StopOutcome {
L287:     // Resolve the stop hook kind from the session source before building the
L288:     // request. Root turns run Stop; thread-spawned child turns run SubagentStop.
L289:     let (target, transcript_path) = match &turn_context.session_source {
L290:         SessionSource::SubAgent(SubAgentSource::ThreadSpawn {
L291:             agent_role,
L292:             parent_thread_id,
L293:             ..
L294:         }) => {
L295:             let context = subagent_hook_context(sess, agent_role);
L296:             let agent_transcript_path = sess.hook_transcript_path().await;
L297:             let parent_transcript_path = match sess
L298:                 .services
L299:                 .thread_store
L300:                 .read_thread(ReadThreadParams {
L301:                     thread_id: *parent_thread_id,
L302:                     include_archived: true,
L303:                     include_history: false,
L304:                 })
L305:                 .await
L306:             {
L307:                 Ok(thread) => thread.rollout_path,
L308:                 Err(error) => {
L309:                     tracing::warn!(
L310:                         parent_thread_id = %parent_thread_id,
L311:                         error = %error,
L312:                         "failed to resolve parent transcript path for subagent hook"
L313:                     );
L314:                     None
L315:                 }
L316:             };
L317:             (
L318:                 StopHookTarget::SubagentStop {
L319:                     agent_id: context.agent_id,
L320:                     agent_type: context.agent_type,
L321:                     agent_transcript_path,
L322:                 },
L323:                 parent_transcript_path,
L324:             )
L325:         }
L326:         // Internal/synthetic subagents do not expose user-configured lifecycle
L327:         // hooks, so there is no Stop or SubagentStop request to dispatch.
L328:         SessionSource::SubAgent(_) => return StopOutcome::default(),
L329:         _ => (StopHookTarget::Stop, sess.hook_transcript_path().await),
L330:     };
L331:     let request = codex_hooks::StopRequest {
L332:         session_id: sess.session_id().into(),
L333:         turn_id: turn_context.sub_id.clone(),
L334:         #[allow(deprecated)]
L335:         cwd: turn_context.cwd.clone(),
L336:         transcript_path,
L337:         model: turn_context.model_info.slug.clone(),
L338:         permission_mode: hook_permission_mode(turn_context),
L339:         stop_hook_active,
L340:         last_assistant_message,
L341:         target,
L342:     };
L343:     let hooks = sess.hooks();
L344:     emit_hook_started_events(sess, turn_context, hooks.preview_stop(&request)).await;
L345:     let mut outcome = hooks.run_stop(request).await;
L346:     emit_hook_completed_events(sess, turn_context, std::mem::take(&mut outcome.hook_events)).await;
L347:     outcome
L348: }
