L438: pub(crate) async fn run_legacy_after_agent_hook(
L439:     sess: &Arc<Session>,
L440:     turn_context: &Arc<TurnContext>,
L441:     input: &[ResponseItem],
L442:     last_assistant_message: Option<String>,
L443: ) -> bool {
L444:     let mut abort_message = None;
L445:     let input_messages = input
L446:         .iter()
L447:         .filter_map(|item| match parse_turn_item(item) {
L448:             Some(TurnItem::UserMessage(user_message)) => Some(user_message.message()),
L449:             _ => None,
L450:         })
L451:         .collect();
L452:     let hooks = sess.hooks();
L453:     for hook_outcome in hooks
L454:         .dispatch(codex_hooks::HookPayload {
L455:             session_id: sess.session_id().into(),
L456:             #[allow(deprecated)]
L457:             cwd: turn_context.cwd.clone(),
L458:             client: turn_context.app_server_client_name.clone(),
L459:             triggered_at: chrono::Utc::now(),
L460:             hook_event: codex_hooks::HookEvent::AfterAgent {
L461:                 event: codex_hooks::HookEventAfterAgent {
L462:                     thread_id: sess.thread_id,
L463:                     turn_id: turn_context.sub_id.clone(),
L464:                     input_messages,
L465:                     last_assistant_message,
L466:                 },
L467:             },
L468:         })
L469:         .await
L470:     {
L471:         let hook_name = hook_outcome.hook_name;
L472:         let (error, should_abort) = match hook_outcome.result {
L473:             codex_hooks::HookResult::Success => continue,
L474:             codex_hooks::HookResult::FailedContinue(error) => (error, false),
L475:             codex_hooks::HookResult::FailedAbort(error) => (error, true),
L476:         };
L477:         let action = if should_abort {
L478:             "aborting operation"
L479:         } else {
L480:             "continuing"
L481:         };
L482:         tracing::warn!(
L483:             turn_id = %turn_context.sub_id,
L484:             hook_name = %hook_name,
L485:             error = %error,
L486:             "after_agent hook failed; {action}"
L487:         );
L488:         if should_abort && abort_message.is_none() {
L489:             abort_message = Some(format!(
L490:                 "after_agent hook '{hook_name}' failed and aborted turn completion: {error}"
L491:             ));
L492:         }
L493:     }
L494:     let Some(message) = abort_message else {
L495:         return false;
L496:     };
L497:     let event = EventMsg::Error(codex_protocol::protocol::ErrorEvent {
L498:         message,
L499:         codex_error_info: Some(CodexErrorInfo::Other),
L500:     });
L501:     sess.send_event(turn_context, event).await;
L502:     true
L503: }
