L643: fn emit_hook_completed_metrics(turn_context: &TurnContext, completed: &HookCompletedEvent) {
L644:     let tags = hook_run_metric_tags(&completed.run);
L645:     turn_context
L646:         .session_telemetry
L647:         .counter(HOOK_RUN_METRIC, /*inc*/ 1, &tags);
L648:     if let Some(duration_ms) = completed.run.duration_ms
L649:         && let Ok(duration_ms) = u64::try_from(duration_ms)
L650:     {
L651:         turn_context.session_telemetry.record_duration(
L652:             HOOK_RUN_DURATION_METRIC,
L653:             Duration::from_millis(duration_ms),
L654:             &tags,
L655:         );
L656:     }
L657: }
