L677:             thread_id,
L678:             completed
L679:                 .turn_id
L680:                 .clone()
L681:                 .unwrap_or_else(|| turn_context.sub_id.clone()),
L682:             turn_context.originator.clone(),
L683:         ),
L684:         HookRunFact {
L685:             event_name: completed.run.event_name,
