L691: fn hook_run_metric_tags(run: &HookRunSummary) -> [(&'static str, &'static str); 3] {
L692:     let hook_name = match run.event_name {
L693:         HookEventName::PreToolUse => "PreToolUse",
L694:         HookEventName::PermissionRequest => "PermissionRequest",
L695:         HookEventName::PostToolUse => "PostToolUse",
L696:         HookEventName::PreCompact => "PreCompact",
L697:         HookEventName::PostCompact => "PostCompact",
L698:         HookEventName::SessionStart => "SessionStart",
L699:         HookEventName::SessionEnd => "SessionEnd",
L700:         HookEventName::UserPromptSubmit => "UserPromptSubmit",
L701:         HookEventName::SubagentStart => "SubagentStart",
